-- PostgreSQL-safe backfill for runtime columns that can drift outside Prisma migrations.
-- This migration is additive and idempotent.

-- 1) student_preferences.response_language (immediate fix)
ALTER TABLE IF EXISTS "student_preferences"
  ADD COLUMN IF NOT EXISTS "response_language" VARCHAR(10) NOT NULL DEFAULT 'en';

-- 2) child_sessions table (if your DB has external child-session tracking)
CREATE TABLE IF NOT EXISTS "child_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "child_id" BIGINT NOT NULL,
  "login_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "logout_at" TIMESTAMP(3),
  "duration_mins" INTEGER,
  "ip_address" VARCHAR(100)
);

CREATE INDEX IF NOT EXISTS "idx_child_sess" ON "child_sessions" ("child_id");
CREATE INDEX IF NOT EXISTS "idx_login_at" ON "child_sessions" ("login_at");

-- 3) children table: trial fields + supabase uid
DO $$
BEGIN
  IF to_regclass('public.children') IS NOT NULL THEN
    ALTER TABLE "children"
      ADD COLUMN IF NOT EXISTS "trial_ends_at" TIMESTAMP(3),
      ADD COLUMN IF NOT EXISTS "subscription_status" VARCHAR(20) NOT NULL DEFAULT 'TRIAL',
      ADD COLUMN IF NOT EXISTS "supabase_uid" VARCHAR(36);

    UPDATE "children"
    SET "trial_ends_at" = NOW() + INTERVAL '3 days'
    WHERE "trial_ends_at" IS NULL;
  END IF;
END $$;

