-- 6) users-style tables: trial fields
DO $$
BEGIN
  IF to_regclass('public.users') IS NOT NULL THEN
    ALTER TABLE "users"
      ADD COLUMN IF NOT EXISTS "trial_ends_at" TIMESTAMP(3),
      ADD COLUMN IF NOT EXISTS "subscription_status" VARCHAR(20) NOT NULL DEFAULT 'TRIAL';

    UPDATE "users"
    SET "trial_ends_at" = NOW() + INTERVAL '3 days'
    WHERE "trial_ends_at" IS NULL;
  END IF;

  IF to_regclass('public."User"') IS NOT NULL THEN
    ALTER TABLE "User"
      ADD COLUMN IF NOT EXISTS "trial_ends_at" TIMESTAMP(3),
      ADD COLUMN IF NOT EXISTS "subscription_status" VARCHAR(20) NOT NULL DEFAULT 'TRIAL';

    UPDATE "User"
    SET "trial_ends_at" = NOW() + INTERVAL '3 days'
    WHERE "trial_ends_at" IS NULL;
  END IF;
END $$;

-- 7) assignments.is_late
DO $$
BEGIN
  IF to_regclass('public.assignments') IS NOT NULL THEN
    ALTER TABLE "assignments"
      ADD COLUMN IF NOT EXISTS "is_late" BOOLEAN NOT NULL DEFAULT false;
  END IF;

  IF to_regclass('public."Assignment"') IS NOT NULL THEN
    ALTER TABLE "Assignment"
      ADD COLUMN IF NOT EXISTS "is_late" BOOLEAN NOT NULL DEFAULT false;
  END IF;
END $$;

-- 8) queries / SearchQuery content flagging columns
DO $$
BEGIN
  IF to_regclass('public.queries') IS NOT NULL THEN
    ALTER TABLE "queries"
      ADD COLUMN IF NOT EXISTS "is_flagged" BOOLEAN NOT NULL DEFAULT false,
      ADD COLUMN IF NOT EXISTS "flag_reason" VARCHAR(255);
  END IF;

  IF to_regclass('public."SearchQuery"') IS NOT NULL THEN
    ALTER TABLE "SearchQuery"
      ADD COLUMN IF NOT EXISTS "is_flagged" BOOLEAN NOT NULL DEFAULT false,
      ADD COLUMN IF NOT EXISTS "flag_reason" VARCHAR(255);
  END IF;
END $$;
